      SUBROUTINE TFLCC     DISTURBANCE AT MAGNET EXIT TO TRANSPORT VARIABLES DUE TOC     MISALIGNMENTCC ----------------------------------------------------------------------C      INCLUDE 'ELM8D.CIN'      INCLUDE 'ELM8H.CIN'CC     LOCAL VARIABLESC      INTEGER         J, JK, K, N      REAL            SC      DO 10 JK = 1, 36   10 CTL(JK) = 0.0      CT1(1,2) = XR(3)      CT1(2,1) = - CT1(1,2)      CT1(3,1) = XR(2)      CT1(1,3) = - CT1(3,1)      CT1(2,3) = XR(1)      CT1(3,2) = - CT1(2,3)C      DO 30  J = 1, 3      DO 30  K = 1, 3      CT(2*J-1,2*K-1) = OR(J,K)      S = 0.0      DO 20 N = 1, 3      S = S + OR(J,N)*CT1(N,K)   20 CONTINUE      CT(2*J-1,2*K) = S   30 CONTINUEC      DO 40 K = 1, 3      CT(2,2*K) = OR(2,K)      CT(4,2*K) = - OR(1,K)   40 CONTINUEC      DO 50 J = 1, 6   50 CONTINUE      RETURN      END